-- HAND-WRITTEN from the report of scripts/probe-maps.mjs on macOS 26.6
-- (fingerprint 2bbc03143125, 146 objects, 54 entities). NOT captured.
--
-- The difference matters and is not a formality. packages/safari's fixture was
-- captured with `--write` and immediately showed three columns the hand-written
-- guess it replaced had missed. This one carries only the columns the probe
-- REPORTED, so it is certain to be missing others, and it cannot contain a
-- column whose existence nobody suspected.
--
-- Capture the real thing with `pnpm probe:maps --write` on a machine that holds
-- Full Disk Access, and delete this header when you do.
--
-- Column names below are the probe's own output. Types are inferred from what
-- Core Data emits for each attribute kind, and are the least trustworthy part.
-- Schema only. No data.

CREATE TABLE Z_PRIMARYKEY (Z_ENT INTEGER PRIMARY KEY, Z_NAME VARCHAR, Z_SUPER INTEGER, Z_MAX INTEGER);
CREATE TABLE Z_METADATA (Z_VERSION INTEGER PRIMARY KEY, Z_UUID VARCHAR(255), Z_PLIST BLOB);

CREATE TABLE ZMIXINMAPITEM (
  Z_PK INTEGER PRIMARY KEY, Z_ENT INTEGER, Z_OPT INTEGER,
  ZCOLLECTIONPLACEITEM INTEGER, ZFAVORITEITEM INTEGER, ZHISTORYPLACEITEM INTEGER,
  ZLATITUDE FLOAT, ZLONGITUDE FLOAT,
  ZCREATETIME TIMESTAMP, ZMODIFICATIONTIME TIMESTAMP,
  ZMAPITEMSTORAGE BLOB
);

CREATE TABLE ZFAVORITEITEM (
  Z_PK INTEGER PRIMARY KEY, Z_ENT INTEGER, Z_OPT INTEGER,
  ZHIDDEN INTEGER, ZMUID INTEGER, ZPOSITIONINDEX INTEGER, ZSOURCE INTEGER,
  ZTYPE INTEGER, ZVERSION INTEGER, ZMAPITEM INTEGER,
  ZLATITUDE FLOAT, ZLONGITUDE FLOAT,
  ZCREATETIME TIMESTAMP, ZMODIFICATIONTIME TIMESTAMP,
  ZCUSTOMNAME VARCHAR, ZMAPITEMNAME VARCHAR,
  ZMAPITEMADDRESS VARCHAR, ZORIGINATINGADDRESSSTRING VARCHAR,
  ZIDENTIFIER BLOB
);

CREATE TABLE ZCOLLECTION (
  Z_PK INTEGER PRIMARY KEY, Z_ENT INTEGER, Z_OPT INTEGER,
  ZPLACESCOUNT INTEGER, ZPOSITIONINDEX INTEGER,
  ZCREATETIME TIMESTAMP, ZMODIFICATIONTIME TIMESTAMP,
  ZTITLE VARCHAR,
  ZIDENTIFIER BLOB, ZIMAGE BLOB
);

-- ZCOLLECTION is the membership key this fixture ASSUMES. The probe found no
-- such column on the real store, so `store.ts` discovers it among candidates
-- and degrades when none is present. `store.test.ts` covers both paths, and the
-- degraded one is the case the real machine is currently believed to hit.
CREATE TABLE ZCOLLECTIONITEM (
  Z_PK INTEGER PRIMARY KEY, Z_ENT INTEGER, Z_OPT INTEGER,
  ZCOLLECTION INTEGER,
  ZPOSITIONINDEX INTEGER, ZDROPPEDPINFLOORORDINAL INTEGER, ZMUID INTEGER,
  ZORIGIN INTEGER, ZTYPE INTEGER, ZMAPITEM INTEGER,
  ZLATITUDE FLOAT, ZLONGITUDE FLOAT,
  ZCREATETIME TIMESTAMP, ZMODIFICATIONTIME TIMESTAMP,
  ZCUSTOMNAME VARCHAR, ZMAPITEMNAME VARCHAR, ZMAPITEMADDRESS VARCHAR,
  ZIDENTIFIER BLOB, ZORIGINALIDENTIFIER BLOB, ZDROPPEDPINCOORDINATE BLOB,
  ZTRANSITLINESTORAGE BLOB
);

-- Two latitude columns, which is not a mistake in this fixture. The probe
-- measured ZLATITUDE populated on 1 row of 33 and ZLATITUDE1 on 19 of 33, and
-- resolving the field by NAME rather than by COVERAGE picks the empty one.
CREATE TABLE ZHISTORYITEM (
  Z_PK INTEGER PRIMARY KEY, Z_ENT INTEGER, Z_OPT INTEGER,
  ZPOSITIONINDEX INTEGER, ZNAVIGATIONINTERRUPTED INTEGER, ZFLOORORDINAL INTEGER,
  ZMUID INTEGER, ZTYPE INTEGER, ZMAPITEM INTEGER,
  ZLATITUDE FLOAT, ZLONGITUDE FLOAT, ZLATITUDE1 FLOAT, ZLONGITUDE1 FLOAT,
  ZCREATETIME TIMESTAMP, ZMODIFICATIONTIME TIMESTAMP,
  ZCUSTOMNAME VARCHAR, ZLOCATIONDISPLAY VARCHAR,
  ZIDENTIFIER BLOB, ZMAPITEMSTORAGE BLOB, ZGEOMAPREGION BLOB
);

CREATE TABLE ZREVIEWEDPLACE (
  Z_PK INTEGER PRIMARY KEY, Z_ENT INTEGER, Z_OPT INTEGER,
  ZMUID INTEGER, ZPOSITIONINDEX INTEGER, ZRATING INTEGER, ZMAPITEM INTEGER,
  ZLATITUDE FLOAT, ZLONGITUDE FLOAT,
  ZCREATETIME TIMESTAMP, ZMODIFICATIONTIME TIMESTAMP,
  ZIDENTIFIER BLOB, ZMAPITEMSTORAGE BLOB
);
